func carrier(t *testing.T, source sparse.Source) ([]byte, string) {
	t.Helper()
	var output bytes.Buffer
	scheme, digest, err := tarstream.WriteTo(context.Background(), &output, "image", source)
	if err != nil {
		t.Fatal(err)
	}
	return output.Bytes(), scheme + ":" + digest
}

func input(t *testing.T, data []byte) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "artifact with spaces.tar")
	if err := os.WriteFile(path, data, 0600); err != nil {
		t.Fatal(err)
	}
	return path
}

type zeroSource struct{ sparse.Source }
type zeroRun struct{ off, end uint64 }

func (r zeroRun) Offset() uint64       { return r.off }
func (r zeroRun) End() uint64          { return r.end }
func (r zeroRun) Kind() sparse.RunKind { return sparse.Zero }
func (r zeroRun) ReadAt(_ context.Context, p []byte, _ uint64) (int, error) {
	clear(p)
	return len(p), nil
}
func (s zeroSource) RunAt(off, limit uint64) (sparse.Run, error) {
	return zeroRun{off, min(s.Size(), off+limit)}, nil
}

func TestReferenceCarrierForms(t *testing.T) {
	page := make([]byte, 4096)
	hole, err := sparse.NewSource(bytes.NewReader(page), 4096, []sparse.Extent{{Size: 4096}})
	if err != nil {
		t.Fatal(err)
	}
	for name, source := range map[string]sparse.Source{
		"legacy-dense":  sparse.Dense(bytes.NewReader([]byte("payload")), 7),
		"presence-data": sparse.Dense(bytes.NewReader(bytes.Repeat([]byte{1}, 4096)), 4096),
		"presence-zero": zeroSource{sparse.Dense(bytes.NewReader(page), 4096)},
		"presence-hole": hole,
	} {
		t.Run(name, func(t *testing.T) {
			data, want := carrier(t, source)
			path := input(t, data)
			var output bytes.Buffer
			if err := run([]string{path}, &output); err != nil {
				t.Fatal(err)
			}
			if output.String() != want+"\n" {
				t.Fatalf("got %q, want %q", output.String(), want)
			}
			after, err := os.ReadFile(path)
			if err != nil || !bytes.Equal(data, after) {
				t.Fatal("reader changed artifact", err)
			}
		})
	}
}

func TestRecordedLegacySparseCarriers(t *testing.T) {
	// Exact accelerator #186 testdata generated by pre-presence 9577691.
	// Embedded compressed bytes keep this regression independent of the tested
	// dependency's fixture inventory (including older released libraries).
	for name, fixture := range legacyCarriers {
		t.Run(name, func(t *testing.T) {
			compressed, err := base64.StdEncoding.DecodeString(fixture.gzip)
			if err != nil {
				t.Fatal(err)
			}
			reader, err := gzip.NewReader(bytes.NewReader(compressed))
			if err != nil {
				t.Fatal(err)
			}
			data, err := io.ReadAll(reader)
			if err != nil {
				t.Fatal(err)
			}
			if err := reader.Close(); err != nil {
				t.Fatal(err)
			}
			got, err := reference(input(t, data))
			if err != nil || got != "digest:"+fixture.digest {
				t.Fatalf("%q: %v", got, err)
			}
		})
	}
}

func TestRejectMalformedCanonicalArtifacts(t *testing.T) {
	for _, payload := range [][]byte{[]byte("payload"), bytes.Repeat([]byte{1}, 4096)} {
		data, _ := carrier(t, sparse.Dense(bytes.NewReader(payload), uint64(len(payload))))
		marker := len(data) - 2048
		for name, mutate := range map[string]func([]byte) []byte{
			"truncated":        func(p []byte) []byte { return p[:len(p)-1] },
			"trailing":         func(p []byte) []byte { return append(p, 0) },
			"missing-marker":   func(p []byte) []byte { return append(p[:marker], make([]byte, 1024)...) },
			"duplicate-marker": func(p []byte) []byte { return append(append([]byte{}, p[:len(p)-1024]...), p[marker:]...) },
			"marker-checksum":  func(p []byte) []byte { p[marker+148] ^= 1; return p },
			"marker-name":      func(p []byte) []byte { p[marker+15] = 'z'; checksum(p[marker : marker+512]); return p },
			"marker-link":      func(p []byte) []byte { p[marker+156] = '2'; checksum(p[marker : marker+512]); return p },
			"payload-size":     func(p []byte) []byte { p[marker+512+7] ^= 1; return p },
			"commitment":       func(p []byte) []byte { p[marker+512+8] ^= 1; return p },
			"marker-padding":   func(p []byte) []byte { p[marker+512+40] = 1; return p },
			"trailer":          func(p []byte) []byte { p[len(p)-1] = 1; return p },
		} {
			t.Run(fmt.Sprintf("%d/%s", len(payload), name), func(t *testing.T) {
				var output bytes.Buffer
				if err := run([]string{input(t, mutate(append([]byte{}, data...)))}, &output); err == nil {
					t.Fatal("corrupt carrier accepted")
				}
				if output.Len() != 0 {
					t.Fatal("identity emitted before validation")
				}
			})
		}
	}
}

func checksum(header []byte) {
	for i := 148; i < 156; i++ {
		header[i] = ' '
	}
	sum := 0
	for _, b := range header {
		sum += int(b)
	}
	copy(header[148:156], fmt.Sprintf("%06o\x00 ", sum))
}

func TestRejectOrdinaryTarAndNonFiles(t *testing.T) {
	var data bytes.Buffer
	tw := tar.NewWriter(&data)
	if err := tw.WriteHeader(&tar.Header{Name: "payload", Mode: 0600, Size: 1}); err != nil {
		t.Fatal(err)
	}
	if _, err := tw.Write([]byte{1}); err != nil {
		t.Fatal(err)
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	fifo := filepath.Join(t.TempDir(), "fifo")
	if err := syscall.Mkfifo(fifo, 0600); err != nil {
		t.Fatal(err)
	}
	for _, path := range []string{input(t, data.Bytes()), t.TempDir(), fifo, filepath.Join(t.TempDir(), "absent")} {
		if _, err := reference(path); err == nil {
			t.Fatalf("accepted %s", path)
		}
	}
	for _, args := range [][]string{nil, {"one", "two"}} {
		if err := run(args, io.Discard); err == nil {
			t.Fatal("accepted invalid arguments")
		}
	}
}

